class AsyncTeamThreadResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def list(
        self, team: str, *, tags: builtins.list[str] | None = None
    ) -> TeamThreadListResponse:
        """
        List threads for a team
        Returns all threads owned by the specified team that the authenticated caller
        has permission to view. The caller must have access to the team; requests
        without team access are rejected with 404.
        Threads are returned in a single `data` array, ordered with the team's
        default thread first, then by most recent activity (newest first). Each
        thread carries a `last_activity` timestamp the most recent message's
        creation time, falling back to the thread's own creation time. Use the
        team-scoped thread endpoints to create, update, or delete individual
        threads.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            tags: Optional: only return threads tagged with at least one of these tags (OR-match). Repeated query params, e.g. `?tags[]=blocked&tags[]=needs-review`.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if tags is not None:
            query["tags"] = tags
        return await self._http.request(
            f"/api/v1/teams/{team}/threads",
            query=query,
            response_type=TeamThreadListResponse,
        )

    async def create(self, team: str, input: TeamThreadCreateInput) -> Thread:
        """
        Create a thread for a team
        Creates a new thread owned by the specified team. The authenticated caller must
        have access to the team; requests from callers without team access are rejected
        with 404.
        If a `profile_picture` is provided in the thread params, it must be
        base64-encoded image data. The image is uploaded and associated with the thread
        before creation completes. Omit `profile_picture` to skip this step.
        By default the platform sends an automatic welcome message into the new thread.
        Pass `skip_welcome_message: true` to suppress this behavior, for example when
        creating threads programmatically in bulk or seeding test data.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            input: Request body.
            input.skip_welcome_message: When `true`, suppresses the automatic welcome message that is otherwise sent into the thread on creation. Defaults to `false`.
            input.thread: Attributes for the new thread. See ThreadCreateParams for available fields.

        Returns:
            The newly created thread.
        """
        return await self._http.request(
            f"/api/v1/teams/{team}/threads",
            method="POST",
            body=input,
            response_type=Thread,
        )

    async def metrics(self, team: str, *, days: int | None = None) -> TeamThreadMetricsResponse:
        """
        Get threads-created count for a team
        Returns how many **network-public** team threads were created in the UTC-day
        window. Counts come from realtime SQL aggregation over append-only
        `network_activity_events` (`thread.created` rows co-committed with create):
        team- or restricted-visibility threads (plus legacy open-team rows), never
        private or mirror. Every Network member sees the same number. Hard-delete
        co-commits a separate `thread.deleted` transition event and does not remove
        create events (metric is "created", not "still present"). Visibility flips
        after insert are ignored in v1.
        Any authenticated team member may read this count-only Network summary.
        Requests from callers without team access return 404 so team existence is
        not disclosed.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            days: UTC-day window. One of 7, 30, 90, or 365; defaults to 30.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if days is not None:
            query["days"] = days
        return await self._http.request(
            f"/api/v1/teams/{team}/threads/metrics",
            query=query,
            response_type=TeamThreadMetricsResponse,
        )


class AsyncTeamResource:
    def __init__(self, http: HttpClient):
        self._http = http
        self.custom_objects = AsyncTeamCustomObjectResource(http)
        self.members = AsyncMemberResource(http)
        self.tasks = AsyncTeamTaskResource(http)
        self.threads = AsyncTeamThreadResource(http)

    async def list(
        self,
        *,
        page: int | None = None,
        page_size: int | None = None,
        search: str | None = None,
        metadata: dict[str, Any] | None = None,
        membership: str | None = None,
    ) -> TeamListResponse:
        """
        List teams
        Returns a paginated list of teams visible to the authenticated user, ordered
        by creation time descending. Use `membership` to narrow results to teams the
        caller has joined or teams they are eligible to join based on their ACL
        visibility.
        Supports full-text search across team name and description via `search`, and
        structured metadata filtering via `metadata`. When `app` is present, results
        are scoped to that app and the caller must hold the corresponding app scope.

        Args:
            page: Page number to retrieve, starting at 1. Defaults to 1.
            page_size: Number of teams to return per page. Defaults to 25.
            search: Full-text search string matched against team name and description.
            metadata: Structured metadata filter expression. Only teams whose metadata satisfies the expression are returned.
            membership: Filter teams by membership status. `"joined"` returns only teams the caller is a member of. `"joinable"` returns ACL-visible teams the caller has not yet joined. Omit to return all visible teams.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if page is not None:
            query["page"] = page
        if page_size is not None:
            query["page_size"] = page_size
        if search is not None:
            query["search"] = search
        if metadata is not None:
            query["metadata"] = metadata
        if membership is not None:
            query["membership"] = membership
        return await self._http.request(
            "/api/v1/teams",
            query=query,
            response_type=TeamListResponse,
        )

    async def create(self, input: TeamCreateInput) -> Team:
        """
        Create a team
        Creates a new team and returns the created team object. The authenticated
        user becomes the team's owner.
        When `app` is supplied, the request is scoped to that app and the caller
        must hold the corresponding app scope. Omit `org` unless you want the team
        pinned to a specific organization. A default chat thread is provisioned for
        the team automatically after creation.

        Args:
            input: Request body.
            input.acl: Access control configuration for the team. Controls who can discover and join the team.
            input.description: Optional human-readable description of the team's purpose.
            input.idempotency_key: Optional retry key. Replays in the same app, organization, and sandbox return the original team.
            input.metadata: Arbitrary key-value pairs you can attach to the team for your own use. Values must be strings.
            input.name: Display name for the team.
            input.org: Organization ID (`org_...`) to associate the team with. Omit to create the team without an org affiliation.

        Returns:
            The newly created team.
        """
        return await self._http.request(
            "/api/v1/teams",
            method="POST",
            body=input,
            response_type=Team,
        )

    async def join_by_code(self, input: TeamJoinByCodeInput) -> Team:
        """
        Join a team with an invite code
        Adds a principal to a team using a 12-character invite code. The invite
        code can be supplied as either `join_code` or `invite_code`; both are
        accepted for backwards compatibility.
        For user-authenticated requests, the currently authenticated user is added
        to the team. For server-to-server requests, you must supply either `agent`
        (to add an agent) or `user` (to add a specific user by ID). If the user
        is already a member of the team, the request succeeds without creating a
        duplicate membership.
        This endpoint is rate-limited to 10 requests per minute per IP address to
        prevent invite-code enumeration.

        Args:
            input: Request body.
            input.agent: Agent ID (`agent_...`) to add to the team. When provided, the agent is joined instead of the authenticated user. Requires a server-to-server session.
            input.invite_code: 12-character invite code alias for `join_code` accepted for backwards compatibility.
            input.join_code: 12-character invite code that identifies the team. Mutually usable with `invite_code`.
            input.user: User ID (`user_...`) to add to the team. Required for server-to-server requests when `agent` is not supplied.

        Returns:
            The team the principal has joined.
        """
        return await self._http.request(
            "/api/v1/teams/join_by_code",
            method="POST",
            body=input,
            response_type=Team,
        )

    async def delete(self, team: str) -> None:
        """
        Delete a team
        Permanently deletes the team identified by `team`. This action is
        irreversible all team memberships, settings, and associated data are
        removed.
        The caller must be the team owner or an org admin. When `app` is present,
        the caller must also hold the corresponding app scope.

        Args:
            team: Team ID (`team_...`) of the team to delete.

        Returns:
            Empty response the team has been deleted.
        """
        await self._http.request(f"/api/v1/teams/{team}", method="DELETE")

    async def get(self, team: str) -> Team:
        """
        Retrieve a team
        Returns the full team object for the given `team` ID, including its current
        member list and all associated threads.
        The authenticated user must be a member of the team or hold a role that
        grants visibility (org admin, app scope). When `app` is supplied, the
        caller must hold the corresponding app scope.

        Args:
            team: Team ID (`team_...`) of the team to retrieve.

        Returns:
            The requested team, including its members and threads.
        """
        return await self._http.request(f"/api/v1/teams/{team}", response_type=Team)

    async def update(self, team: str, input: TeamUpdateInput) -> Team:
        """
        Update a team
        Updates one or more attributes of the team identified by `team`. Only the
        fields you provide are changed; omitted fields are left as-is.
        To replace the team's profile picture, supply the `profile_picture` object
        with base64-encoded image data. The previous picture is deleted after the
        new one is successfully uploaded. When `app` is present, the caller must hold
        the corresponding app scope. The caller must be a team owner or org admin.

        Args:
            team: Team ID (`team_...`) of the team to update.
            input: Request body.
            input.acl: New access control configuration for the team. Replaces the existing ACL.
            input.description: New human-readable description of the team's purpose.
            input.metadata: Arbitrary key-value pairs to set on the team. Replaces the existing metadata map entirely.
            input.name: New display name for the team.
            input.profile_picture: New profile picture for the team. Provide this object to upload and replace the current picture.

        Returns:
            The updated team with all changes applied.
        """
        return await self._http.request(
            f"/api/v1/teams/{team}",
            method="PATCH",
            body=input,
            response_type=Team,
        )

    async def artifacts(self, team: str) -> TeamArtifactsResponse:
        """
        List a team's artifacts
        Returns all artifacts owned by the specified team. Artifacts represent
        AI-generated or user-uploaded files associated with agent sessions,
        threads, or sandboxes such as images, documents, and code outputs.
        The authenticated user must be a member of the team. Attempting to list
        artifacts for a team the caller does not have access to returns 404
        rather than 403 to avoid leaking team existence.
        Results are returned in a single page without cursor pagination. Each
        artifact in the response reflects the state of its current version,
        including a short-lived signed `file_url` for direct download.

        Args:
            team: Team ID (`tea_...`). The authenticated user must be a member of this team.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/teams/{team}/artifacts",
            response_type=TeamArtifactsResponse,
        )

    async def invite(self, team: str) -> TeamInvite:
        """
        Create a team invite
        Generates a new invite code for the specified team. The authenticated user
        must be a member of the team with the `owner` or `admin` role.
        The returned code is a short alphanumeric string that other users can
        present to join the team. Each call produces a new code; previously issued
        codes are not invalidated by this request.

        Args:
            team: Team ID (`tm_...`) identifying the team for which to generate the invite code.

        Returns:
            The newly created team invite containing the join code.
        """
        return await self._http.request(
            f"/api/v1/teams/{team}/invite",
            method="POST",
            response_type=TeamInvite,
        )

    async def invites(self, team: str) -> TeamInvitesResponse:
        """
        Create a team invite (server-to-server)
        Generates a new invite code for the specified team using server-to-server
        authentication. Unlike the user-facing create endpoint, this variant does not
        require the caller to be a team member it is intended for privileged
        back-end services acting on behalf of your platform.
        The returned code is a short alphanumeric string that users can present to
        join the team. Each call produces a new code; previously issued codes are
        not invalidated by this request.

        Args:
            team: Team ID (`tm_...`) identifying the team for which to generate the invite code.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/teams/{team}/invites",
            method="POST",
            response_type=TeamInvitesResponse,
        )

    async def join(self, team: str, input: TeamJoinInput) -> None:
        """
        Join a team
        Adds a principal to a team that is visible to the authenticated user.
        By default, the currently authenticated user joins the team. Provide `agent`
        to add an agent to the team instead the caller must already be a member of
        the team to do so. Provide `user` (by ID) or `email` to add another user from
        your organization the caller must be a team owner, team admin, or org admin.
        Only one of `agent`, `user`, or `email` may be supplied per request.
        If the target principal is already a member of the team, the request succeeds
        without creating a duplicate membership. Server-to-server callers are not
        permitted to use this endpoint; use the invite-code endpoint instead.

        Args:
            team: Team ID (`team_...`) to join.
            input: Request body.
            input.agent: Agent ID (`agent_...`) to add to the team. The caller must already be a member of the team.
            input.email: Email address of a member of the caller's organization to add to the team. Requires team-owner, team-admin, or org-admin role.
            input.user: User ID (`user_...`) of a member of the caller's organization to add to the team. Requires team-owner, team-admin, or org-admin role.

        Returns:
            Empty response the principal is now a member of the team.
        """
        await self._http.request(f"/api/v1/teams/{team}/join", method="POST", body=input)

    async def leave(self, team: str) -> None:
        """
        Leave a team
        Removes a principal from a team. By default, the authenticated user removes
        themselves from the team. Provide `agent` to remove an agent instead the
        caller must be a member of the team to do so.
        Team owners cannot leave their own team. To transfer ownership first, use
        the update-membership endpoint, then call this endpoint.
        For server-to-server requests, `user` is required to identify which user
        should be removed.

        Args:
            team: Team ID (`team_...`) to leave.

        Returns:
            Empty response the principal has been removed from the team.
        """
        await self._http.request(f"/api/v1/teams/{team}/leave", method="DELETE")

    async def task_assignees(
        self, team: str, *, org: str | None = None
    ) -> TeamTaskAssigneesResponse:
        """
        List task assignees for a team
        Returns the list of principals users and agents that can be assigned
        to tasks within the team. Results include both human members and AI agents
        and are sorted alphabetically by display name.
        This endpoint is only available for team-scoped contexts. Calling it with a
        user-scoped owner returns a 400 error. The authenticated user must be a
        member of the team or hold org-admin access. App-scoped developer and
        server-to-server callers may list assignees for teams in their app so they
        can select the explicit user or agent actor required by privileged task
        mutations.

        Args:
            team: Team ID (`tem_...`).
            org: Explicit organization (`org_...`) for developer and server-to-server calls. Pass null for a team outside an organization.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if org is not None:
            query["org"] = org
        return await self._http.request(
            f"/api/v1/teams/{team}/task_assignees",
            query=query,
            response_type=TeamTaskAssigneesResponse,
        )


class TeamCustomObjectResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(
        self,
        team: str,
        type: str,
        *,
        limit: int | None = None,
        offset: int | None = None,
        row_key: str | None = None,
        sort_key: str | None = None,
        query: str | None = None,
    ) -> TeamCustomObjectListResponse:
        """
        List a team's custom objects
        Returns a paginated list of custom objects owned by the specified team,
        filtered to a single schema type. Results are ordered by creation time
        descending unless `query` is provided, in which case they are ordered by
        full-text relevance score descending.
        Use `limit` and `offset` for page-based pagination. Use `row_key` or
        `sort_key` to narrow results to objects matching those index values.
        Full-text search via `query` operates only against the fields configured
        as `search_fields` on the schema.
        The authenticated user must be a member of the team with sufficient
        access. Returns 404 if the team is not found, the caller lacks access,
        or `type` does not match a registered schema for the team's organization.

        Args:
            team: Team ID (`team_...`). Scopes results to objects owned by this team.
            type: Schema type identifier (`lookup_key`) that filters results to objects of this schema.
            limit: Maximum number of objects to return per page.
            offset: Number of objects to skip before returning results. Use with `limit` for page-based pagination.
            row_key: Filter results to objects whose `row_key` exactly matches this value.
            sort_key: Filter results to objects whose `sort_key` exactly matches this value.
            query: Full-text search string matched against the schema's configured `search_fields`. When provided, results are ordered by relevance score descending instead of creation time descending.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        query["type"] = type
        if limit is not None:
            query["limit"] = limit
        if offset is not None:
            query["offset"] = offset
        if row_key is not None:
            query["row_key"] = row_key
        if sort_key is not None:
            query["sort_key"] = sort_key
        if query is not None:
            query["query"] = query
        return self._http.request(
            f"/api/v1/teams/{team}/custom_objects",
            query=query,
            response_type=TeamCustomObjectListResponse,
        )

    def create(self, team: str, input: TeamCustomObjectCreateInput) -> CustomObject:
        """
        Create a team custom object
        Creates a new custom object owned by the specified team. The object is
        instantiated against the schema identified by `type` (the schema's
        `lookup_key`). All field values are validated against that schema's
        field definitions before the object is persisted.
        The authenticated user must be a member of the team with sufficient
        access. If the team is not found or the caller lacks access, the endpoint
        returns 404. If `type` does not match a registered schema for the team's
        organization, the endpoint also returns 404.

        Args:
            team: Team ID (`team_...`). Scopes results to objects owned by this team.
            input: Request body.
            input.fields: Map of field values to set on the new object. Keys and value types must conform to the schema identified by `type`.
            input.type: Schema type identifier (`lookup_key`) that defines the object's fields and validation rules.

        Returns:
            The newly created custom object.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/custom_objects",
            method="POST",
            body=input,
            response_type=CustomObject,
        )


class MemberResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def remove(self, team: str) -> None:
        """
        Remove a member or org from a team
        Removes a user, agent, or all members of an organization from the specified
        team. Provide exactly one of `user`, `agent`, or `org` supplying more than
        one or none returns a 400 error. On success, returns 204 No Content.
        When `org` is provided, every user and agent membership belonging to that org
        is removed in a single call. The caller must be a member of the team's owning
        org to perform an org-scoped removal. You cannot target the team's owning org
        itself with this parameter.
        The caller must have permission to manage the team. When `app` is present, the
        request is scoped to that app and requires a valid app-scoped token.

        Args:
            team: Team ID (`team_...`). The team to remove the member from.

        Returns:
            Empty response. Returns 204 No Content on success.
        """
        self._http.request(f"/api/v1/teams/{team}/members", method="DELETE")

    def list(self, team: str) -> MemberListResponse:
        """
        List members of a team
        Returns all members of the specified team, including both users and agents.
        Members are returned in a single non-paginated array ordered by join time.
        Bearer-authenticated users must be a member of the team to retrieve its
        member list. Developer and server-to-server callers can retrieve members for
        any team visible to their app scope. When `app` is provided, the request is
        scoped to that app and requires a valid app-scoped token.

        Args:
            team: Team ID (`team_...`). The team to remove the member from.

        Returns:
            Successful response
        """
        return self._http.request(f"/api/v1/teams/{team}/members", response_type=MemberListResponse)

    def create(self, team: str, input: MemberCreateInput) -> TeamMembership:
        """
        Add a member to a team
        Adds a user or agent as a member of the specified team and returns the new
        membership with HTTP 201. Provide exactly one of `user` or `agent` supplying
        both or neither returns a 400 error.
        Adding a user requires permission to manage the team (team owner, team
        admin, or org admin). Adding an agent with the default `"member"` role is
        also open to any existing member of the team; assigning an elevated role to
        an agent still requires team-manage permission. When an `app` is provided,
        the request is scoped to that app and the caller must hold a valid app-scoped
        token. The default role is `"member"` when `role` is omitted.

        Args:
            team: Team ID (`team_...`). The team to remove the member from.
            input: Request body.
            input.agent: Agent ID (`agt_...`) to add as a member. Provide exactly one of `user` or `agent`.
            input.role: Role to assign. One of `"owner"`, `"admin"`, or `"member"`. Defaults to `"member"` when omitted.
            input.user: User ID (`usr_...`) to add as a member. Provide exactly one of `user` or `agent`.

        Returns:
            The newly created team membership.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/members",
            method="POST",
            body=input,
            response_type=TeamMembership,
        )

    def update(self, team: str, user: str, input: MemberUpdateInput) -> TeamMembership:
        """
        Update a team member's role
        Changes the role of an existing user member on the specified team. Returns the
        updated membership on success.
        Only user memberships are supported by this endpoint. Attempting to update an
        agent membership returns 404. To change an agent's role, remove the existing
        membership and re-add the agent with the desired role.
        The caller must have permission to modify the team. You cannot change a member's
        role across organization boundaries. Demoting the last owner of a team returns
        409. An invalid `role` value returns 422. When `app` is provided, the request
        is scoped to that app and requires a valid app-scoped token.

        Args:
            team: Team ID (`team_...`). The team to remove the member from.
            user: User ID (`usr_...`) of the existing member whose role should be changed.
            input: Request body.
            input.role: New role to assign. One of `"owner"`, `"admin"`, or `"member"`.

        Returns:
            The updated team membership reflecting the new role.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/members/{user}",
            method="PATCH",
            body=input,
            response_type=TeamMembership,
        )


class TeamTaskResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(
        self,
        team: str,
        *,
        user: str | None = None,
        org: str | None = None,
        status: str | None = None,
        owner_user: str | None = None,
        owner_agent: str | None = None,
        priority: int | None = None,
        tag: str | None = None,
        parent: str | None = None,
        source_scope: str | None = None,
        source_type: str | None = None,
        source_id: str | None = None,
        epic: str | None = None,
        search: str | None = None,
        sort: str | None = None,
        order: str | None = None,
        due_before: str | None = None,
        due_after: str | None = None,
        overdue: bool | None = None,
        ready: bool | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> TeamTaskListResponse:
        """
        List an owner's tasks
        Returns tasks owned by the specified user or team. You can narrow results using the
        optional filters below. By default results are returned in reverse chronological
        order (most recently created first); use `sort` and `order` to sort by due date or
        priority instead.
        User-authenticated callers may list their personal tasks or tasks for teams they
        have joined. Privileged callers provide the owner in the route; the owner's
        organization is implied by that principal. An explicit `org` is optional and,
        when set, must match the owner's organization.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            user: User ID (`usr_...`) for user-scoped tasks.
            org: Optional organization (`org_...`) for developer and server-to-server calls. When omitted, the org is taken from the owner principal (team, user, or agent). When set, it must match that principal's org; pass null for an owner outside an organization.
            status: Filter tasks by status. One of `"open"`, `"in_progress"`, or `"done"`. Omit to return tasks in all statuses.
            owner_user: Filter tasks assigned to a specific user. Provide the user's public ID (`usr_...`).
            owner_agent: Filter tasks assigned to a specific agent. Provide the agent's public ID (`agi_...`).
            priority: Filter tasks by priority, from 0 (highest) to 4 (lowest).
            tag: Return only tasks carrying this tag (matched against the canonical lowercase form).
            parent: Return only subtasks of the given task (`tsk_...`), or pass `none` to return only top-level tasks.
            source_scope: Return only tasks whose source matches this container. Must be supplied with `source_type` and `source_id`.
            source_type: Return only tasks whose source matches this object kind. Must be supplied with the other source filters.
            source_id: Return only tasks whose source matches this object identity. Must be supplied with the other source filters.
            epic: Return only tasks with this exact epic label.
            search: Restrict results to tasks whose name or description contains this string.
            sort: Sort key. One of `"created"` (default most recently created first), `"due_date"` (soonest due first; tasks without a due date always sort last), or `"priority"` (most urgent first). Ties break by most recently created.
            order: Sort direction, `"asc"` or `"desc"`. Defaults to `"desc"` for `created` and `"asc"` for `due_date` and `priority`.
            due_before: Return only tasks with a due date strictly before this ISO 8601 datetime (`2026-08-01T00:00:00Z`) or date (`2026-08-01`, meaning midnight UTC). Tasks without a due date are excluded.
            due_after: Return only tasks with a due date strictly after this ISO 8601 datetime or date. Tasks without a due date are excluded.
            overdue: When `true`, return only overdue tasks: a due date before the current UTC day and a status other than `"done"`. A task due today is not overdue.
            ready: When true, return only open tasks with no unfinished blockers and no active session lease. This is a projection snapshot; claim a lease before starting work.
            limit: Maximum number of tasks to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        if org is not None:
            query["org"] = org
        if status is not None:
            query["status"] = status
        if owner_user is not None:
            query["owner_user"] = owner_user
        if owner_agent is not None:
            query["owner_agent"] = owner_agent
        if priority is not None:
            query["priority"] = priority
        if tag is not None:
            query["tag"] = tag
        if parent is not None:
            query["parent"] = parent
        if source_scope is not None:
            query["source_scope"] = source_scope
        if source_type is not None:
            query["source_type"] = source_type
        if source_id is not None:
            query["source_id"] = source_id
        if epic is not None:
            query["epic"] = epic
        if search is not None:
            query["search"] = search
        if sort is not None:
            query["sort"] = sort
        if order is not None:
            query["order"] = order
        if due_before is not None:
            query["due_before"] = due_before
        if due_after is not None:
            query["due_after"] = due_after
        if overdue is not None:
            query["overdue"] = overdue
        if ready is not None:
            query["ready"] = ready
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/teams/{team}/tasks",
            query=query,
            response_type=TeamTaskListResponse,
        )

    def create(self, team: str, input: TeamTaskCreateInput) -> Task:
        """
        Create a task for an owner
        Creates a new task owned by the specified user or team and returns the full
        task object. User-authenticated calls are attributed to the authenticated
        user or agent. App-scoped developer and server-to-server callers must provide
        the task's explicit `org` scope and an explicit `user` or `agent` actor for
        team tasks; a user-owned task reuses the user in the route unless an explicit
        agent is supplied. Every referenced principal is validated against the app,
        owner, and team membership before creation.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            input: Request body.
            input.agent: Explicit acting agent (`agi_...`) for a developer or server-to-server call. Mutually exclusive with an acting `user`; the agent must belong to the task owner.
            input.org: Explicit organization (`org_...`) for developer and server-to-server calls. Pass null when the owner is not organization-scoped. The value must match the selected user or team.
            input.task: Attributes for the task to create. `name` is required; all other fields are optional.
            input.user: User ID (`usr_...`). On a user route this is the task owner and creator; on a team route it is the explicit acting user for a developer or server-to-server call.

        Returns:
            The newly created task.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/tasks",
            method="POST",
            body=input,
            response_type=Task,
        )

    def blocker_cycles(
        self,
        team: str,
        *,
        user: str | None = None,
        org: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> TeamTaskBlockerCyclesResponse:
        """
        List task blocker cycles
        Runs an on-demand diagnostic over unfinished tasks owned by the specified
        team or user and returns a forward cursor-paginated page of complete cyclic
        blocker components. Detection is bounded to owners with at most 100
        unfinished tasks. This endpoint is read-only: cycles do not prevent task
        updates, lease acquisition, or completion.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            user: User ID (`usr_...`) owning the tasks.
            org: Optional organization context for privileged callers.
            limit: Maximum cycle components to return. Defaults to 50; maximum is 100.
            after_cursor: Opaque cursor returned by the preceding page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        if org is not None:
            query["org"] = org
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/teams/{team}/tasks/blocker_cycles",
            query=query,
            response_type=TeamTaskBlockerCyclesResponse,
        )

    def metrics(self, team: str, *, days: int | None = None) -> TeamTaskMetricsResponse:
        """
        Get task activity metrics for a team
        Returns task activity metrics scoped to one team (the Network in ArchAgents).
        `open` counts currently open or in-progress team tasks, `created` counts
        tasks inserted in the UTC-day window, and `completed` counts tasks whose
        `closed_at` falls in that window while still in a closed status. Hard-deleted
        tasks are absent from the projection and therefore omitted. The daily series
        is zero-filled across the requested window and includes reconstructed
        end-of-day `open` stock (from remaining projection rows' inserted_at/closed_at).
        Any authenticated team member may read this count-only Network summary.
        Requests from callers without team access return 404 so team existence is
        not disclosed.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            days: UTC-day window. One of 7, 30, 90, or 365; defaults to 30.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if days is not None:
            query["days"] = days
        return self._http.request(
            f"/api/v1/teams/{team}/tasks/metrics",
            query=query,
            response_type=TeamTaskMetricsResponse,
        )

    def ready(
        self,
        team: str,
        *,
        user: str | None = None,
        org: str | None = None,
        explain: bool | None = None,
        assigned_to_me: bool | None = None,
        source_scope: str | None = None,
        source_type: str | None = None,
        source_id: str | None = None,
        epic: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> TeamTaskReadyResponse:
        """
        List an owner's ready tasks
        Returns open tasks with no unfinished blockers and no active session lease.
        Readiness is calculated by the server from the current task projection. It is
        a snapshot, not a reservation; claim a task lease before starting work.
        Pass `explain=true` to include every open task with a stable readiness reason.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            user: User ID (`usr_...`) owning the tasks.
            org: Optional organization context for privileged callers.
            explain: Include blocked and actively leased open tasks with exclusion reasons.
            assigned_to_me: Only include tasks assigned to the authenticated user.
            source_scope: Only include tasks whose source matches this container. Must be supplied with `source_type` and `source_id`.
            source_type: Only include tasks whose source matches this object kind.
            source_id: Only include tasks whose source matches this object identity.
            epic: Only include tasks with this exact epic label.
            limit: Maximum number of readiness entries to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        if org is not None:
            query["org"] = org
        if explain is not None:
            query["explain"] = explain
        if assigned_to_me is not None:
            query["assigned_to_me"] = assigned_to_me
        if source_scope is not None:
            query["source_scope"] = source_scope
        if source_type is not None:
            query["source_type"] = source_type
        if source_id is not None:
            query["source_id"] = source_id
        if epic is not None:
            query["epic"] = epic
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/teams/{team}/tasks/ready",
            query=query,
            response_type=TeamTaskReadyResponse,
        )

    def search(
        self,
        team: str,
        *,
        user: str | None = None,
        org: str | None = None,
        q: str | None = None,
        query: str | None = None,
        status: str | None = None,
        owner_user: str | None = None,
        owner_agent: str | None = None,
        priority: int | None = None,
        tag: str | None = None,
        parent: str | None = None,
        source_scope: str | None = None,
        source_type: str | None = None,
        source_id: str | None = None,
        epic: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> TeamTaskSearchResponse:
        """
        Search an owner's tasks
        Performs a full-text search over tasks owned by the specified user or team and returns
        matching results. Combine `q` with the optional filters to narrow the result set
        further. When no query is provided, the endpoint behaves like a filtered list.
        The `query` field in the response echoes the effective search query.
        User-authenticated callers may search their personal tasks or tasks for teams
        they have joined. Privileged callers provide the owner in the route; the owner's
        organization is implied by that principal. An explicit `org` is optional and,
        when set, must match the owner's organization.

        Args:
            team: Team ID (`tem_...`). Only tasks belonging to this team are returned.
            user: User ID (`usr_...`) whose tasks are searched.
            org: Optional organization (`org_...`) for developer and server-to-server calls. When omitted, the org is taken from the owner principal (team, user, or agent). When set, it must match that principal's org; pass null for an owner outside an organization.
            q: Full-text search query matched against task names and descriptions. Takes precedence over `query` when both are provided.
            query: Alias for `q`. Use `q` when possible; this parameter exists for compatibility.
            status: Filter results by status. One of `"open"`, `"in_progress"`, or `"done"`. Omit to include all statuses.
            owner_user: Restrict results to tasks assigned to the user with this public ID (`usr_...`).
            owner_agent: Restrict results to tasks assigned to the agent with this public ID (`agi_...`).
            priority: Filter results by priority, from 0 (highest) to 4 (lowest).
            tag: Return only tasks carrying this tag (matched against the canonical lowercase form).
            parent: Return only subtasks of the given task (`tsk_...`), or pass `none` to return only top-level tasks.
            source_scope: Return only tasks whose source matches this container. Must be supplied with `source_type` and `source_id`.
            source_type: Return only tasks whose source matches this object kind.
            source_id: Return only tasks whose source matches this object identity.
            epic: Return only tasks with this exact epic label.
            limit: Maximum number of tasks to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        if org is not None:
            query["org"] = org
        if q is not None:
            query["q"] = q
        if query is not None:
            query["query"] = query
        if status is not None:
            query["status"] = status
        if owner_user is not None:
            query["owner_user"] = owner_user
        if owner_agent is not None:
            query["owner_agent"] = owner_agent
        if priority is not None:
            query["priority"] = priority
        if tag is not None:
            query["tag"] = tag
        if parent is not None:
            query["parent"] = parent
        if source_scope is not None:
            query["source_scope"] = source_scope
        if source_type is not None:
            query["source_type"] = source_type
        if source_id is not None:
            query["source_id"] = source_id
        if epic is not None:
            query["epic"] = epic
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/teams/{team}/tasks/search",
            query=query,
            response_type=TeamTaskSearchResponse,
        )


class TeamThreadResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(self, team: str, *, tags: builtins.list[str] | None = None) -> TeamThreadListResponse:
        """
        List threads for a team
        Returns all threads owned by the specified team that the authenticated caller
        has permission to view. The caller must have access to the team; requests
        without team access are rejected with 404.
        Threads are returned in a single `data` array, ordered with the team's
        default thread first, then by most recent activity (newest first). Each
        thread carries a `last_activity` timestamp the most recent message's
        creation time, falling back to the thread's own creation time. Use the
        team-scoped thread endpoints to create, update, or delete individual
        threads.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            tags: Optional: only return threads tagged with at least one of these tags (OR-match). Repeated query params, e.g. `?tags[]=blocked&tags[]=needs-review`.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if tags is not None:
            query["tags"] = tags
        return self._http.request(
            f"/api/v1/teams/{team}/threads",
            query=query,
            response_type=TeamThreadListResponse,
        )

    def create(self, team: str, input: TeamThreadCreateInput) -> Thread:
        """
        Create a thread for a team
        Creates a new thread owned by the specified team. The authenticated caller must
        have access to the team; requests from callers without team access are rejected
        with 404.
        If a `profile_picture` is provided in the thread params, it must be
        base64-encoded image data. The image is uploaded and associated with the thread
        before creation completes. Omit `profile_picture` to skip this step.
        By default the platform sends an automatic welcome message into the new thread.
        Pass `skip_welcome_message: true` to suppress this behavior, for example when
        creating threads programmatically in bulk or seeding test data.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            input: Request body.
            input.skip_welcome_message: When `true`, suppresses the automatic welcome message that is otherwise sent into the thread on creation. Defaults to `false`.
            input.thread: Attributes for the new thread. See ThreadCreateParams for available fields.

        Returns:
            The newly created thread.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/threads",
            method="POST",
            body=input,
            response_type=Thread,
        )

    def metrics(self, team: str, *, days: int | None = None) -> TeamThreadMetricsResponse:
        """
        Get threads-created count for a team
        Returns how many **network-public** team threads were created in the UTC-day
        window. Counts come from realtime SQL aggregation over append-only
        `network_activity_events` (`thread.created` rows co-committed with create):
        team- or restricted-visibility threads (plus legacy open-team rows), never
        private or mirror. Every Network member sees the same number. Hard-delete
        co-commits a separate `thread.deleted` transition event and does not remove
        create events (metric is "created", not "still present"). Visibility flips
        after insert are ignored in v1.
        Any authenticated team member may read this count-only Network summary.
        Requests from callers without team access return 404 so team existence is
        not disclosed.

        Args:
            team: Team ID (`tem_...`) whose threads should be listed.
            days: UTC-day window. One of 7, 30, 90, or 365; defaults to 30.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if days is not None:
            query["days"] = days
        return self._http.request(
            f"/api/v1/teams/{team}/threads/metrics",
            query=query,
            response_type=TeamThreadMetricsResponse,
        )


class TeamResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http
        self.custom_objects = TeamCustomObjectResource(http)
        self.members = MemberResource(http)
        self.tasks = TeamTaskResource(http)
        self.threads = TeamThreadResource(http)

    def list(
        self,
        *,
        page: int | None = None,
        page_size: int | None = None,
        search: str | None = None,
        metadata: dict[str, Any] | None = None,
        membership: str | None = None,
    ) -> TeamListResponse:
        """
        List teams
        Returns a paginated list of teams visible to the authenticated user, ordered
        by creation time descending. Use `membership` to narrow results to teams the
        caller has joined or teams they are eligible to join based on their ACL
        visibility.
        Supports full-text search across team name and description via `search`, and
        structured metadata filtering via `metadata`. When `app` is present, results
        are scoped to that app and the caller must hold the corresponding app scope.

        Args:
            page: Page number to retrieve, starting at 1. Defaults to 1.
            page_size: Number of teams to return per page. Defaults to 25.
            search: Full-text search string matched against team name and description.
            metadata: Structured metadata filter expression. Only teams whose metadata satisfies the expression are returned.
            membership: Filter teams by membership status. `"joined"` returns only teams the caller is a member of. `"joinable"` returns ACL-visible teams the caller has not yet joined. Omit to return all visible teams.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if page is not None:
            query["page"] = page
        if page_size is not None:
            query["page_size"] = page_size
        if search is not None:
            query["search"] = search
        if metadata is not None:
            query["metadata"] = metadata
        if membership is not None:
            query["membership"] = membership
        return self._http.request("/api/v1/teams", query=query, response_type=TeamListResponse)

    def create(self, input: TeamCreateInput) -> Team:
        """
        Create a team
        Creates a new team and returns the created team object. The authenticated
        user becomes the team's owner.
        When `app` is supplied, the request is scoped to that app and the caller
        must hold the corresponding app scope. Omit `org` unless you want the team
        pinned to a specific organization. A default chat thread is provisioned for
        the team automatically after creation.

        Args:
            input: Request body.
            input.acl: Access control configuration for the team. Controls who can discover and join the team.
            input.description: Optional human-readable description of the team's purpose.
            input.idempotency_key: Optional retry key. Replays in the same app, organization, and sandbox return the original team.
            input.metadata: Arbitrary key-value pairs you can attach to the team for your own use. Values must be strings.
            input.name: Display name for the team.
            input.org: Organization ID (`org_...`) to associate the team with. Omit to create the team without an org affiliation.

        Returns:
            The newly created team.
        """
        return self._http.request("/api/v1/teams", method="POST", body=input, response_type=Team)

    def join_by_code(self, input: TeamJoinByCodeInput) -> Team:
        """
        Join a team with an invite code
        Adds a principal to a team using a 12-character invite code. The invite
        code can be supplied as either `join_code` or `invite_code`; both are
        accepted for backwards compatibility.
        For user-authenticated requests, the currently authenticated user is added
        to the team. For server-to-server requests, you must supply either `agent`
        (to add an agent) or `user` (to add a specific user by ID). If the user
        is already a member of the team, the request succeeds without creating a
        duplicate membership.
        This endpoint is rate-limited to 10 requests per minute per IP address to
        prevent invite-code enumeration.

        Args:
            input: Request body.
            input.agent: Agent ID (`agent_...`) to add to the team. When provided, the agent is joined instead of the authenticated user. Requires a server-to-server session.
            input.invite_code: 12-character invite code alias for `join_code` accepted for backwards compatibility.
            input.join_code: 12-character invite code that identifies the team. Mutually usable with `invite_code`.
            input.user: User ID (`user_...`) to add to the team. Required for server-to-server requests when `agent` is not supplied.

        Returns:
            The team the principal has joined.
        """
        return self._http.request(
            "/api/v1/teams/join_by_code",
            method="POST",
            body=input,
            response_type=Team,
        )

    def delete(self, team: str) -> None:
        """
        Delete a team
        Permanently deletes the team identified by `team`. This action is
        irreversible all team memberships, settings, and associated data are
        removed.
        The caller must be the team owner or an org admin. When `app` is present,
        the caller must also hold the corresponding app scope.

        Args:
            team: Team ID (`team_...`) of the team to delete.

        Returns:
            Empty response the team has been deleted.
        """
        self._http.request(f"/api/v1/teams/{team}", method="DELETE")

    def get(self, team: str) -> Team:
        """
        Retrieve a team
        Returns the full team object for the given `team` ID, including its current
        member list and all associated threads.
        The authenticated user must be a member of the team or hold a role that
        grants visibility (org admin, app scope). When `app` is supplied, the
        caller must hold the corresponding app scope.

        Args:
            team: Team ID (`team_...`) of the team to retrieve.

        Returns:
            The requested team, including its members and threads.
        """
        return self._http.request(f"/api/v1/teams/{team}", response_type=Team)

    def update(self, team: str, input: TeamUpdateInput) -> Team:
        """
        Update a team
        Updates one or more attributes of the team identified by `team`. Only the
        fields you provide are changed; omitted fields are left as-is.
        To replace the team's profile picture, supply the `profile_picture` object
        with base64-encoded image data. The previous picture is deleted after the
        new one is successfully uploaded. When `app` is present, the caller must hold
        the corresponding app scope. The caller must be a team owner or org admin.

        Args:
            team: Team ID (`team_...`) of the team to update.
            input: Request body.
            input.acl: New access control configuration for the team. Replaces the existing ACL.
            input.description: New human-readable description of the team's purpose.
            input.metadata: Arbitrary key-value pairs to set on the team. Replaces the existing metadata map entirely.
            input.name: New display name for the team.
            input.profile_picture: New profile picture for the team. Provide this object to upload and replace the current picture.

        Returns:
            The updated team with all changes applied.
        """
        return self._http.request(
            f"/api/v1/teams/{team}",
            method="PATCH",
            body=input,
            response_type=Team,
        )

    def artifacts(self, team: str) -> TeamArtifactsResponse:
        """
        List a team's artifacts
        Returns all artifacts owned by the specified team. Artifacts represent
        AI-generated or user-uploaded files associated with agent sessions,
        threads, or sandboxes such as images, documents, and code outputs.
        The authenticated user must be a member of the team. Attempting to list
        artifacts for a team the caller does not have access to returns 404
        rather than 403 to avoid leaking team existence.
        Results are returned in a single page without cursor pagination. Each
        artifact in the response reflects the state of its current version,
        including a short-lived signed `file_url` for direct download.

        Args:
            team: Team ID (`tea_...`). The authenticated user must be a member of this team.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/teams/{team}/artifacts",
            response_type=TeamArtifactsResponse,
        )

    def invite(self, team: str) -> TeamInvite:
        """
        Create a team invite
        Generates a new invite code for the specified team. The authenticated user
        must be a member of the team with the `owner` or `admin` role.
        The returned code is a short alphanumeric string that other users can
        present to join the team. Each call produces a new code; previously issued
        codes are not invalidated by this request.

        Args:
            team: Team ID (`tm_...`) identifying the team for which to generate the invite code.

        Returns:
            The newly created team invite containing the join code.
        """
        return self._http.request(
            f"/api/v1/teams/{team}/invite",
            method="POST",
            response_type=TeamInvite,
        )

    def invites(self, team: str) -> TeamInvitesResponse:
        """
        Create a team invite (server-to-server)
        Generates a new invite code for the specified team using server-to-server
        authentication. Unlike the user-facing create endpoint, this variant does not
        require the caller to be a team member it is intended for privileged
        back-end services acting on behalf of your platform.
        The returned code is a short alphanumeric string that users can present to
        join the team. Each call produces a new code; previously issued codes are
        not invalidated by this request.

        Args:
            team: Team ID (`tm_...`) identifying the team for which to generate the invite code.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/teams/{team}/invites",
            method="POST",
            response_type=TeamInvitesResponse,
        )

    def join(self, team: str, input: TeamJoinInput) -> None:
        """
        Join a team
        Adds a principal to a team that is visible to the authenticated user.
        By default, the currently authenticated user joins the team. Provide `agent`
        to add an agent to the team instead the caller must already be a member of
        the team to do so. Provide `user` (by ID) or `email` to add another user from
        your organization the caller must be a team owner, team admin, or org admin.
        Only one of `agent`, `user`, or `email` may be supplied per request.
        If the target principal is already a member of the team, the request succeeds
        without creating a duplicate membership. Server-to-server callers are not
        permitted to use this endpoint; use the invite-code endpoint instead.

        Args:
            team: Team ID (`team_...`) to join.
            input: Request body.
            input.agent: Agent ID (`agent_...`) to add to the team. The caller must already be a member of the team.
            input.email: Email address of a member of the caller's organization to add to the team. Requires team-owner, team-admin, or org-admin role.
            input.user: User ID (`user_...`) of a member of the caller's organization to add to the team. Requires team-owner, team-admin, or org-admin role.

        Returns:
            Empty response the principal is now a member of the team.
        """
        self._http.request(f"/api/v1/teams/{team}/join", method="POST", body=input)

    def leave(self, team: str) -> None:
        """
        Leave a team
        Removes a principal from a team. By default, the authenticated user removes
        themselves from the team. Provide `agent` to remove an agent instead the
        caller must be a member of the team to do so.
        Team owners cannot leave their own team. To transfer ownership first, use
        the update-membership endpoint, then call this endpoint.
        For server-to-server requests, `user` is required to identify which user
        should be removed.

        Args:
            team: Team ID (`team_...`) to leave.

        Returns:
            Empty response the principal has been removed from the team.
        """
        self._http.request(f"/api/v1/teams/{team}/leave", method="DELETE")

    def task_assignees(self, team: str, *, org: str | None = None) -> TeamTaskAssigneesResponse:
        """
        List task assignees for a team
        Returns the list of principals users and agents that can be assigned
        to tasks within the team. Results include both human members and AI agents
        and are sorted alphabetically by display name.
        This endpoint is only available for team-scoped contexts. Calling it with a
        user-scoped owner returns a 400 error. The authenticated user must be a
        member of the team or hold org-admin access. App-scoped developer and
        server-to-server callers may list assignees for teams in their app so they
        can select the explicit user or agent actor required by privileged task
        mutations.

        Args:
            team: Team ID (`tem_...`).
            org: Explicit organization (`org_...`) for developer and server-to-server calls. Pass null for a team outside an organization.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if org is not None:
            query["org"] = org
        return self._http.request(
            f"/api/v1/teams/{team}/task_assignees",
            query=query,
            response_type=TeamTaskAssigneesResponse,
        )
